<script lang="ts">
 export let rows:any[]=[]; export let decisions:any[]=[]; export let roster:any[]=[]; export let aliases:any[]=[]; export let nameChanges:any[]=[]; export let language='en'; export let readOnly=false;
 export let onDecision:(decision:any)=>Promise<void>=async()=>{}; export let onRevert:(id:string)=>Promise<void>=async()=>{};
 let expanded=new Set<string>(); let selected:Record<string,number>={}; let query:Record<string,string>={}; let splitIds:Record<string,number[]>={}; let busy=''; let error='';
 const t=(zh:string,en:string)=>language==='zh-CN'?zh:en;
 const norm=(s:string)=>s.toLocaleLowerCase().replace(/[\s\p{P}\p{S}\u3000]/gu,'');
 $: pending=Array.from(new Map(rows.filter(r=>r.matchStatus==='unmatched').map(r=>[r.entityId||r.sessionParticipantId,r])).values());
 $: renamed=(()=>{const byParticipant=new Map<string,any[]>();for(const change of nameChanges){const id=change.sessionParticipantId;if(!id||decisions.some(d=>d.sessionParticipantId===id&&Date.parse(d.createdAt||'')>=Date.parse(change.timestamp||'')))continue;byParticipant.set(id,[...(byParticipant.get(id)||[]),change]);}return Array.from(byParticipant,([id,changes])=>{const ordered=changes.slice().sort((a,b)=>Date.parse(a.timestamp||'')-Date.parse(b.timestamp||''));const earliest=ordered[0],latest=ordered[ordered.length-1];return {...rows.find(r=>r.sessionParticipantId===id),...earliest,...latest,previousScreenName:earliest.previousScreenName||earliest.previous_screen_name,nextScreenName:latest.nextScreenName||latest.next_screen_name,zoomName:latest.nextScreenName||latest.next_screen_name,entityId:id,sessionParticipantId:id}})})();
 $: resolved=decisions;
 function candidates(r:any){const n=norm(r.zoomName||'');return roster.filter(p=>p.active!==false&&(norm(p.canonicalName||'')===n||norm(p.pinyin||'')===n||aliases.some(a=>Number(a.personId)===Number(p.personId)&&norm(a.zoomName||a.alias||'')===n)));}
 function label(r:any){return r.zoomName||r.screenName||'—'}
 function findPerson(id:number){return roster.find(p=>Number(p.personId)===Number(id))}
 function make(r:any,action:string,personId?:number,splitPersonIds?:number[]){const prior=aliases.find(a=>norm(a.zoomName||a.alias||'')===norm(r.previousScreenName||''));const p=findPerson(personId||r.personId||prior?.personId||0);const people=(splitPersonIds||[]).map(findPerson).filter(Boolean);return {id:`decision-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,sessionParticipantId:r.sessionParticipantId||r.entityId,zoomName:label(r),zoomNameAtDecision:label(r),action,...(p?{personId:p.personId,canonicalName:p.canonicalName}:{}),...(people.length?{splitPersonIds:people.map(x=>x.personId),splitCanonicalNames:people.map(x=>x.canonicalName)}:{}),createdAt:new Date().toISOString()}}
 async function act(r:any,action:string,id?:number,ids?:number[]){busy=r.entityId||r.sessionParticipantId;error='';try{await onDecision(make(r,action,id,ids));expanded.delete(busy)}catch(e:any){error=e.message||String(e)}finally{busy=''}}
 function toggle(r:any){const id=r.entityId||r.sessionParticipantId;if(!expanded.has(id)&&r.previousScreenName&&!splitIds[id]){const prior=aliases.find(a=>norm(a.zoomName||a.alias||'')===norm(r.previousScreenName));splitIds[id]=[prior?.personId||0,0]}expanded.has(id)?expanded.delete(id):expanded.add(id);expanded=new Set(expanded)}
 function canKeep(r:any){return !!r.personId||aliases.some(a=>norm(a.zoomName||a.alias||'')===norm(r.previousScreenName||''))}
 function addSplit(r:any){const id=r.entityId||r.sessionParticipantId;splitIds[id]=[...(splitIds[id]||[]),0];splitIds={...splitIds}}
 function dropSplit(r:any,index:number){const id=r.entityId||r.sessionParticipantId;splitIds[id]=(splitIds[id]||[]).filter((_,i)=>i!==index);splitIds={...splitIds}}
 function options(r:any){const q=norm(query[r.entityId]||'');return roster.filter(p=>p.active!==false&&(!q||norm(`${p.canonicalName} ${p.pinyin} ${p.personId}`).includes(q)))}
</script>

<section class="panel name-matching" data-testid="name-matching-panel">
 <div class="panel-title"><div><h2>{t('名称匹配','Name Matching')}</h2><p>{t('未匹配、名称变更与已处理决定','Unmatched names, name changes, and resolved decisions')}</p></div><span class="warning-count">{pending.length+renamed.length} {t('待处理','pending')}</span></div>
 {#if error}<p role="alert" class="error">{error}</p>{/if}
 <h3>{t('待匹配','Pending')}</h3>
 {#each pending as r (r.entityId)}
  {@const c=candidates(r)} {@const id=r.entityId||r.sessionParticipantId} {@const duplicates=rows.filter(x=>norm(x.zoomName||'')===norm(r.zoomName||'')).length>1}
  <article class="match-card"><div class="match-heading"><b title={label(r)}>{label(r)}</b>{#if duplicates}<small>#{String(r.participantUUID||r.entityId).slice(-4)}</small>{/if}<span>{c.length?c.map(x=>x.canonicalName).join(', '):t('未匹配','Unmatched')}</span></div>
   <div class="match-actions">{#each c as p}<button disabled={!!busy||readOnly} onclick={()=>act(r,'match',p.personId)}>{t('关联','Match')} {p.canonicalName}</button>{/each}
    {#if r.sharedName}<button disabled={!!busy||readOnly} onclick={()=>{splitIds[id]=c.slice(0,2).map(x=>x.personId);splitIds={...splitIds};toggle(r)}}>{t(`拆分共享名称 (${c.length})`,`Split Shared (${c.length})`)}</button>{/if}
    {#if !c.length}<button disabled={!!busy||readOnly} onclick={()=>act(r,'guest')}>{t('标记来宾','Mark Guest')}</button>{/if}
    <button class="more" aria-expanded={expanded.has(id)} onclick={()=>toggle(r)}>{t('更多 ▾','More ▾')}</button>
   </div>
   {#if expanded.has(id)}<div class="manual"><label>{t('手动关联','Manual Match')} <input aria-label={t('搜索花名册','Search roster')} bind:value={query[id]} placeholder={t('姓名、拼音或编号','Name, pinyin, or ID')}/></label><select aria-label={t('选择人员','Select person')} bind:value={selected[id]}><option value={0}>{t('选择人员…','Choose a person…')}</option>{#each options(r) as p}<option value={p.personId}>{p.canonicalName} · {p.pinyin} · #{p.personId}</option>{/each}</select><button disabled={!selected[id]||!!busy||readOnly} onclick={()=>act(r,'match',selected[id])}>{t('确认关联','Confirm Match')}</button>
    <fieldset><legend>{t('共用账号拆分','Shared Account Split')}</legend>{#each splitIds[id]||[] as pid,i}<div class="split-row"><select aria-label={t(`拆分人员 ${i+1}`,`Split person ${i+1}`)} bind:value={splitIds[id][i]}><option value={0}>{t('选择人员…','Choose a person…')}</option>{#each roster.filter(p=>p.active!==false) as p}<option value={p.personId}>{p.canonicalName} · {p.pinyin} · #{p.personId}</option>{/each}</select><button aria-label={t('移除此人','Remove person')} onclick={()=>dropSplit(r,i)}>×</button></div>{/each}<button onclick={()=>addSplit(r)}>{t('添加人员','Add person')}</button><button disabled={(new Set((splitIds[id]||[]).filter(Boolean))).size<2||!!busy||readOnly} onclick={()=>act(r,'split',undefined,splitIds[id])}>{t('确认拆分','Confirm Split')}</button></fieldset>
   </div>{/if}
  </article>
 {:else}<p class="muted">{t('没有待匹配的参与者。','No unmatched participants.')}</p>{/each}
 <h3>{t('名称变更','Name Changes')}</h3>
 {#each renamed as r (r.entityId)}{@const id=r.entityId}<article class="match-card"><b title={`${r.previousScreenName} → ${r.nextScreenName}`}>{r.previousScreenName} → {r.nextScreenName}</b>{#if canKeep(r)}<button disabled={!!busy||readOnly} onclick={()=>act(r,'name_change_keep_match')}>{t('保持匹配','Keep Match')}</button>{/if}<button class="more" aria-expanded={expanded.has(id)} onclick={()=>toggle(r)}>{t('更多 ▾','More ▾')}</button>{#if expanded.has(id)}<div class="manual"><label>{t('手动关联','Manual Match')}<input bind:value={query[id]} placeholder={t('姓名、拼音或编号','Name, pinyin, or ID')}/></label><select aria-label={t('手动关联','Manual Match')} bind:value={selected[id]}><option value={0}>{t('选择人员…','Choose a person…')}</option>{#each options(r) as p}<option value={p.personId}>{p.canonicalName} · {p.pinyin} · #{p.personId}</option>{/each}</select><button disabled={!selected[id]||!!busy||readOnly} onclick={()=>act(r,'match',selected[id])}>{t('确认关联','Confirm Match')}</button><fieldset><legend>{t('共用账号拆分','Shared Account Split')}</legend>{#each splitIds[id]||[] as pid,i}<div class="split-row"><select aria-label={t(`拆分人员 ${i+1}`,`Split person ${i+1}`)} bind:value={splitIds[id][i]}><option value={0}>{t('选择人员…','Choose a person…')}</option>{#each roster.filter(p=>p.active!==false) as p}<option value={p.personId}>{p.canonicalName} · {p.pinyin}</option>{/each}</select><button onclick={()=>dropSplit(r,i)}>{t('移除','Remove')}</button></div>{/each}<button onclick={()=>addSplit(r)}>{t('添加人员','Add person')}</button><button disabled={new Set((splitIds[id]||[]).filter(Boolean)).size<2||!!busy||readOnly} onclick={()=>act(r,'split',undefined,splitIds[id])}>{t('确认拆分','Confirm Split')}</button></fieldset></div>{/if}</article>{/each}
 <h3>{t('已处理','Resolved')}</h3>
 {#each resolved as d (d.id)}<article class="resolved-row"><span>{d.zoomName}</span><span class="decision-badge">{d.action==='match'?t('已关联','Matched'):d.action==='guest'?t('来宾','Guest'):d.action==='split'?t('共用账号拆分','Shared account split'):d.action==='name_change_keep_match'?t('名称变更保持匹配','Name change keep match'):t('未知','Unknown')}</span>{#if d.canonicalName}<small>{d.canonicalName}</small>{/if}{#if !readOnly}<button class="danger" onclick={()=>onRevert(d.id)}>{t('撤销','Revert')}</button>{/if}</article>{:else}<p class="muted">{t('暂无已处理决定。','No resolved decisions.')}</p>{/each}
</section>

<style>
 .name-matching{margin:16px 0}.panel-title,.match-heading,.match-actions,.resolved-row,.split-row{display:flex;align-items:center;gap:10px}.panel-title{justify-content:space-between}.panel-title h2{margin:0}.panel-title p,.muted{color:var(--muted,#78818f)}h3{font-size:13px;margin:20px 0 8px}.warning-count{color:#a56a00;background:#fff4d6;border-radius:20px;padding:5px 9px}.match-card,.resolved-row{border:1px solid #e5e8ef;border-radius:10px;padding:12px;margin:8px 0}.match-heading span{margin-left:auto;color:var(--muted,#78818f)}.match-actions{flex-wrap:wrap;margin-top:9px}.match-actions button,.manual button,.match-card button,.resolved-row button{font:inherit;cursor:pointer}.manual{padding:12px;background:#f8f9fb;border-radius:8px;margin-top:10px;display:grid;gap:9px}.manual label{display:grid;gap:5px}.manual input,.manual select,.split-row select,.match-card select{padding:8px;border:1px solid #d8dce5;border-radius:6px}.manual fieldset{border:1px solid #d8dce5;border-radius:8px;display:grid;gap:8px}.resolved-row .decision-badge{padding:3px 8px;background:#edf3ff;border-radius:12px}.resolved-row button{margin-left:auto}.error{color:#b42318}
</style>
